def to_base(n, base):
    digits = ''
    while n > 0:
        digits = str(n % base) + digits
        n //= base
    return digits or '0'

answers = []
for n in range(1, 501):
    s = to_base(n, 3)
    if n % 3 == 0:
        s = '1' + s + '02'
    else:
        s += str(n % 3) * 2
    r = int(s, 3)
    if r <= 500:
        answers.append(n)

print(max(answers))
